fn callLlmSimple(allocator: Allocator, user_message: []const u8, api_key: []const u8) ![]const u8 {
    const messages_json = try fmt.allocPrint(allocator,
        \\[{{"role":"user","content":"{s}"}}]
    , .{user_message});
    defer allocator.free(messages_json);
    return callLlmWithMessages(allocator, messages_json, api_key);
}

fn escapeJsonString(allocator: Allocator, s: []const u8) ![]const u8 {
    var out = ArrayList(u8).init(allocator);
    for (s) |c| {
        switch (c) {
            '"' => try out.appendSlice("\\\""),
            '\\' => try out.appendSlice("\\\\"),
            '\n' => try out.appendSlice("\\n"),
            '\r' => try out.appendSlice("\\r"),
            '\t' => try out.appendSlice("\\t"),
            0...8, 11, 12, 14...31 => {
                var tmp: [6]u8 = undefined;
                const s2 = try fmt.bufPrint(&tmp, "\\u{x:0>4}", .{c});
                try out.appendSlice(s2);
            },
            else => try out.append(c),
        }
    }
    return out.toOwnedSlice();
}

fn callLlmWithMessages(allocator: Allocator, messages_json: []const u8, api_key: []const u8) ![]const u8 {
    const body = try fmt.allocPrint(allocator,
        \\{{"model":"{s}","max_tokens":24576,"top_p":1,"top_k":40,"presence_penalty":0,"frequency_penalty":0,"temperature":0.6,"messages":{s}}}
    , .{ FIREWORKS_MODEL, messages_json });
    defer allocator.free(body);

    const auth_header = try fmt.allocPrint(allocator, "Bearer {s}", .{api_key});
    defer allocator.free(auth_header);

    const request = try fmt.allocPrint(allocator,
        "POST /inference/v1/chat/completions HTTP/1.1\r\n" ++
            "Host: {s}\r\n" ++
            "Content-Type: application/json\r\n" ++
            "Authorization: {s}\r\n" ++
            "Content-Length: {d}\r\n" ++
            "Connection: close\r\n" ++
            "\r\n",
        .{ FIREWORKS_HOST, auth_header, body.len },
    );
    defer allocator.free(request);

    const tcp = try net.tcpConnectToHost(allocator, FIREWORKS_HOST, 443);
    defer tcp.close();

    var ca_bundle: crypto.Certificate.Bundle = .{};
    try ca_bundle.rescan(allocator);
    defer ca_bundle.deinit(allocator);

    var tls_client = try crypto.tls.Client.init(tcp, .{
        .host = .{ .explicit = FIREWORKS_HOST },
        .ca = .{ .bundle = ca_bundle },
    });

    try tls_client.writeAll(tcp, request);
    try tls_client.writeAll(tcp, body);

    var response_buf = ArrayList(u8).init(allocator);
    defer response_buf.deinit();
    var rbuf: [4096]u8 = undefined;
    while (true) {
        const n = tls_client.read(tcp, &rbuf) catch break;
        if (n == 0) break;
        try response_buf.appendSlice(rbuf[0..n]);
    }

    const response = response_buf.items;
    const header_end = mem.indexOf(u8, response, "\r\n\r\n") orelse return error.InvalidResponse;
    const resp_body = response[header_end + 4 ..];

    const content = extractLlmContent(allocator, resp_body) catch return allocator.dupe(u8, "No response");
    return content;
}

fn extractLlmContent(allocator: Allocator, body: []const u8) ![]const u8 {
    const parsed = try json.parseFromSlice(json.Value, allocator, body, .{});
    defer parsed.deinit();

    const root = parsed.value;
    if (root != .object) return error.InvalidJson;

    const choices = root.object.get("choices") orelse return error.NoChoices;
    if (choices != .array or choices.array.items.len == 0) return error.NoChoices;

    const first = choices.array.items[0];
    if (first != .object) return error.InvalidChoice;

    const msg = first.object.get("message") orelse return error.NoMessage;
    if (msg != .object) return error.InvalidMessage;

    const content = msg.object.get("content") orelse return error.NoContent;
    if (content != .string) return error.InvalidContent;

    return allocator.dupe(u8, content.string);
}

fn callLlmForAgent(allocator: Allocator, task: []const u8, current_url: []const u8, iteration: u32, history: []const u8, dom_snapshot: []const u8, api_key: []const u8) ![]const u8 {
    const system_prompt =
        \\You are a browser automation agent. You receive the current browser state and must respond with a single JSON object describing the next action. You must always respond with valid JSON only, no prose, no markdown, no code fences.
        \\
        \\Action schema:
        \\{"thought":"string","action":"navigate|click|type|scroll|extract|submit|done","target":"CSS selector or URL","value":"string or empty","done":false}
        \\
        \\Actions:
        \\- navigate: target is a full URL, value is empty
        \\- click: target is a CSS selector, value is empty
        \\- type: target is a CSS selector, value is the text to type
        \\- scroll: target is "up" or "down", value is pixel amount as string
        \\- extract: target is a CSS selector, value is empty - extracts and records text content
        \\- submit: target is a CSS selector of a form, value is empty
        \\- done: set done:true when the task is fully completed
    ;

    const dom_truncated = if (dom_snapshot.len > 12000) dom_snapshot[0..12000] else dom_snapshot;

    const escaped_task = try escapeJsonString(allocator, task);
    defer allocator.free(escaped_task);
    const escaped_url = try escapeJsonString(allocator, current_url);
    defer allocator.free(escaped_url);
    const escaped_dom = try escapeJsonString(allocator, dom_truncated);
    defer allocator.free(escaped_dom);
    const escaped_history = try escapeJsonString(allocator, history);
    defer allocator.free(escaped_history);
    const escaped_system = try escapeJsonString(allocator, system_prompt);
    defer allocator.free(escaped_system);

    const user_content = try fmt.allocPrint(allocator,
        "Task: {s}\\nCurrent URL: {s}\\nIteration: {d}/40\\nPrevious actions: {s}\\nCurrent page state:\\n{s}",
        .{ task, current_url, iteration, history, dom_truncated },
    );
    defer allocator.free(user_content);

    const escaped_user = try escapeJsonString(allocator, user_content);
    defer allocator.free(escaped_user);

    const messages_json = try fmt.allocPrint(allocator,
        \\[{{"role":"system","content":"{s}"}},{{"role":"user","content":"{s}"}}]
    , .{ escaped_system, escaped_user });
    defer allocator.free(messages_json);

    return callLlmWithMessages(allocator, messages_json, api_key);
}

