const CdpClient = struct {
    stream: net.Stream,
    next_id: u32,
    allocator: Allocator,

    fn connect(allocator: Allocator) !CdpClient {
        const target_url = try getChromeTargetUrl(allocator);
        defer allocator.free(target_url);

        const host = "localhost";
        const port: u16 = CHROME_DEBUG_PORT;

        const stream = try net.tcpConnectToAddress(try net.Address.parseIp4("127.0.0.1", port));
        errdefer stream.close();

        var key_bytes: [16]u8 = undefined;
        crypto.random.bytes(&key_bytes);
        var key_b64: [24]u8 = undefined;
        _ = std.base64.standard.Encoder.encode(&key_b64, &key_bytes);

        const handshake = try fmt.allocPrint(allocator,
            "GET {s} HTTP/1.1\r\n" ++
                "Host: {s}:{d}\r\n" ++
                "Upgrade: websocket\r\n" ++
                "Connection: Upgrade\r\n" ++
                "Sec-WebSocket-Key: {s}\r\n" ++
                "Sec-WebSocket-Version: 13\r\n" ++
                "\r\n",
            .{ target_url, host, port, key_b64 },
        );
        defer allocator.free(handshake);
        try stream.writeAll(handshake);

        var resp_buf: [2048]u8 = undefined;
        var resp_len: usize = 0;
        while (resp_len < resp_buf.len - 1) {
            var one: [1]u8 = undefined;
            const n = try stream.read(&one);
            if (n == 0) break;
            resp_buf[resp_len] = one[0];
            resp_len += 1;
            if (resp_len >= 4 and mem.eql(u8, resp_buf[resp_len - 4 .. resp_len], "\r\n\r\n")) break;
        }

        const resp = resp_buf[0..resp_len];
        if (!mem.startsWith(u8, resp, "HTTP/1.1 101")) {
            return error.WebSocketUpgradeFailed;
        }

        return CdpClient{
            .stream = stream,
            .next_id = 1,
            .allocator = allocator,
        };
    }

    fn deinit(self: *CdpClient) void {
        self.stream.close();
    }

    fn sendFrame(self: *CdpClient, data: []const u8) !void {
        var mask: [4]u8 = undefined;
        crypto.random.bytes(&mask);

        var header: [14]u8 = undefined;
        var hlen: usize = 2;
        header[0] = 0x81; // FIN + text opcode
        if (data.len <= 125) {
            header[1] = 0x80 | @as(u8, @intCast(data.len));
        } else if (data.len <= 65535) {
            header[1] = 0xFE;
            header[2] = @intCast((data.len >> 8) & 0xFF);
            header[3] = @intCast(data.len & 0xFF);
            hlen = 4;
        } else {
            header[1] = 0xFF;
            header[2] = 0;
            header[3] = 0;
            header[4] = 0;
            header[5] = 0;
            header[6] = @intCast((data.len >> 24) & 0xFF);
            header[7] = @intCast((data.len >> 16) & 0xFF);
            header[8] = @intCast((data.len >> 8) & 0xFF);
            header[9] = @intCast(data.len & 0xFF);
            hlen = 10;
        }
        header[hlen] = mask[0];
        header[hlen + 1] = mask[1];
        header[hlen + 2] = mask[2];
        header[hlen + 3] = mask[3];
        hlen += 4;

        const masked = try self.allocator.alloc(u8, data.len);
        defer self.allocator.free(masked);
        for (data, 0..) |b, i| {
            masked[i] = b ^ mask[i % 4];
        }

        try self.stream.writeAll(header[0..hlen]);
        try self.stream.writeAll(masked);
    }

    fn recvFrame(self: *CdpClient, out: *ArrayList(u8)) !bool {
        var header: [2]u8 = undefined;
        var n = try self.stream.readAll(&header);
        if (n < 2) return error.ConnectionClosed;

        const fin = (header[0] & 0x80) != 0;
        const opcode = header[0] & 0x0F;
        const masked = (header[1] & 0x80) != 0;
        var payload_len: usize = header[1] & 0x7F;

        if (payload_len == 126) {
            var ext: [2]u8 = undefined;
            n = try self.stream.readAll(&ext);
            if (n < 2) return error.ConnectionClosed;
            payload_len = (@as(usize, ext[0]) << 8) | ext[1];
        } else if (payload_len == 127) {
            var ext: [8]u8 = undefined;
            n = try self.stream.readAll(&ext);
            if (n < 8) return error.ConnectionClosed;
            payload_len = (@as(usize, ext[4]) << 24) | (@as(usize, ext[5]) << 16) | (@as(usize, ext[6]) << 8) | ext[7];
