            0x8 => return error.ConnectionClosed,
            0x9 => {
                var pong: [2]u8 = .{ 0x8A, 0x00 };
                _ = self.stream.writeAll(&pong) catch {};
            },
            0xA => {},
            else => {
                try out.appendSlice(payload);
            },
        }

        return fin;
    }

    fn recvMessage(self: *CdpClient) ![]const u8 {
        var buf = ArrayList(u8).init(self.allocator);
        errdefer buf.deinit();
        while (true) {
