            const raw = try self.recvMessage();
            defer self.allocator.free(raw);

            const parsed = json.parseFromSlice(json.Value, self.allocator, raw, .{}) catch continue;
            defer parsed.deinit();

            if (parsed.value != .object) continue;

            const msg_id = parsed.value.object.get("id") orelse {
