// 1. Chrome spawn
fn spawnChrome(allocator: Allocator) !void {
    chrome_mutex.lock();
    defer chrome_mutex.unlock();
    if (chrome_child != null) return;

    const argv = [_][]const u8{
        "google-chrome",
        "--remote-debugging-port=9222",
        "--no-first-run",
        "--no-default-browser-check",
        "--disable-background-networking",
        "--disable-sync",
        "--disable-translate",
        "--disable-extensions",
        "--disable-default-apps",
        "--disable-popup-blocking",
        "--user-data-dir=/tmp/agent-chrome-profile",
        "--headless=new",
    };
    var child = process.Child.init(&argv, allocator);
    child.stdout_behavior = .Ignore;
    child.stderr_behavior = .Ignore;
    try child.spawn();
    chrome_child = child;

    // Polling: max 5s, 100ms interval
    var attempts: u32 = 0;
    while (attempts < 50) : (attempts += 1) {
        std.time.sleep(100 * std.time.ns_per_ms);
        const ok = checkChromeReady(allocator) catch false;
        if (ok) return;
    }
    return error.ChromeStartTimeout;
}

// 2. Chrome ready check
fn checkChromeReady(allocator: Allocator) !bool {
    const stream = net.tcpConnectToAddress(
        try net.Address.parseIp4("127.0.0.1", CHROME_DEBUG_PORT)
    ) catch return false;
    defer stream.close();

    const req = "GET /json/version HTTP/1.1\r\nHost: localhost:9222\r\nConnection: close\r\n\r\n";
    try stream.writeAll(req);
    var buf: [2048]u8 = undefined;
    const n = try stream.readAll(&buf);
    _ = allocator;
    return mem.indexOf(u8, buf[0..n], "200 OK") != null;
}

// 3. Get WebSocket target URL
fn getChromeTargetUrl(allocator: Allocator) ![]const u8 {
    const stream = try net.tcpConnectToAddress(
        try net.Address.parseIp4("127.0.0.1", CHROME_DEBUG_PORT)
    );
    defer stream.close();

    const req = "GET /json/new HTTP/1.1\r\nHost: localhost:9222\r\nConnection: close\r\n\r\n";
    try stream.writeAll(req);

    var buf: [8192]u8 = undefined;
    const n = try stream.readAll(&buf);
    const response = buf[0..n];

    const header_end = mem.indexOf(u8, response, "\r\n\r\n") orelse return error.InvalidResponse;
    const body = response[header_end + 4..];

    const parsed = try json.parseFromSlice(json.Value, allocator, body, .{});
    defer parsed.deinit();

    if (parsed.value != .object) return error.InvalidJson;
    const ws_url = parsed.value.object.get("webSocketDebuggerUrl") orelse return error.NoWsUrl;
    if (ws_url != .string) return error.InvalidWsUrl;

    // Extract path from ws://localhost:9222/devtools/page/...
    const url = ws_url.string;
    const path_start = mem.indexOf(u8, url, "/devtools") orelse return error.InvalidWsUrl;
    return allocator.dupe(u8, url[path_start..]);
}

// 4. Chunked response body decoder
fn readHttpBody(allocator: Allocator, stream: anytype, headers: []const u8, raw_body: []const u8) ![]const u8 {
    const is_chunked = mem.indexOf(u8, headers, "chunked") != null;
    if (!is_chunked) return allocator.dupe(u8, raw_body);

    var out = ArrayList(u8).init(allocator);
    var pos: usize = 0;
    while (pos < raw_body.len) {
        const crlf = mem.indexOf(u8, raw_body[pos..], "\r\n") orelse break;
        const size_str = raw_body[pos .. pos + crlf];
        const chunk_size = fmt.parseInt(usize, size_str, 16) catch break;
        if (chunk_size == 0) break;
        pos += crlf + 2;
        if (pos + chunk_size > raw_body.len) break;
        try out.appendSlice(raw_body[pos .. pos + chunk_size]);
        pos += chunk_size + 2; // skip trailing \r\n
    }
    _ = stream;
    return out.toOwnedSlice();
}
