## Az `agentLoop` Vázlata

Ez a legfontosabb hiányzó rész:

```zig
fn agentLoop(run: *AgentRun) void {
    defer {
        run.running.store(false, .seq_cst);
        run.sse_queue.finish();
    }

    const allocator = run.allocator;

    const api_key = process.getEnvVarOwned(allocator, "FIREWORKS_API_KEY") catch {
        run.sse_queue.push("{\"type\":\"error\",\"text\":\"Missing FIREWORKS_API_KEY\"}");
        return;
    };
    defer allocator.free(api_key);

    spawnChrome(allocator) catch |err| {
        const msg = fmt.allocPrint(allocator, "{{\"type\":\"error\",\"text\":\"Chrome spawn failed: {}\"}}", .{err}) catch return;
        defer allocator.free(msg);
        run.sse_queue.push(msg);
        return;
    };

    var cdp = CdpClient.connect(allocator) catch |err| {
        const msg = fmt.allocPrint(allocator, "{{\"type\":\"error\",\"text\":\"CDP connect failed: {}\"}}", .{err}) catch return;
        defer allocator.free(msg);
        run.sse_queue.push(msg);
        return;
    };
    defer cdp.deinit();

    var history = ArrayList(u8).init(allocator);
    defer history.deinit();

    while (run.running.load(.seq_cst) and run.iteration < run.max_iterations) {
        var iter_arena = std.heap.ArenaAllocator.init(allocator);
        defer iter_arena.deinit();
        const ia = iter_arena.allocator();

        run.iteration += 1;

        // 1. DOM snapshot
        const dom = cdp.getDomSnapshot() catch |err| blk: {
            _ = err;
            break :blk allocator.dupe(u8, "{}") catch continue;
        };
        defer allocator.free(dom);

        // 2. Current URL
        const url = cdp.getCurrentUrl() catch allocator.dupe(u8, "unknown") catch continue;
        defer allocator.free(url);
        run.setCurrentUrl(url);

        // 3. LLM call
        const llm_response = callLlmForAgent(
            ia, run.task, url, run.iteration,
            history.items, dom, api_key
        ) catch |err| {
            const msg = fmt.allocPrint(ia, "{{\"type\":\"error\",\"text\":\"LLM error: {}\"}}", .{err}) catch continue;
            run.sse_queue.push(msg);
            continue;
        };

        // 4. Parse action JSON
        const action_parsed = json.parseFromSlice(json.Value, ia, llm_response, .{}) catch {
            run.sse_queue.push("{\"type\":\"error\",\"text\":\"Invalid LLM JSON\"}");
            continue;
        };

        const root = action_parsed.value;
        if (root != .object) continue;

        const thought = if (root.object.get("thought")) |t| (if (t == .string) t.string else "") else "";
        const action = if (root.object.get("action")) |a| (if (a == .string) a.string else "done") else "done";
        const target = if (root.object.get("target")) |t| (if (t == .string) t.string else "") else "";
        const value  = if (root.object.get("value"))  |v| (if (v == .string) v.string else "") else "";
        const is_done = if (root.object.get("done"))  |d| (if (d == .bool) d.bool else false) else false;

        // 5. SSE log
        const log_msg = fmt.allocPrint(ia,
            "{{\"type\":\"step\",\"iteration\":{d},\"thought\":\"{s}\",\"action\":\"{s}\",\"target\":\"{s}\"}}",
            .{ run.iteration, thought, action, target }
        ) catch continue;
        run.sse_queue.push(log_msg);
        run.setLastAction(action);

        // 6. Execute action
        if (mem.eql(u8, action, "navigate")) {
            cdp.navigate(target) catch {};
        } else if (mem.eql(u8, action, "click")) {
            cdp.clickElement(target) catch {};
        } else if (mem.eql(u8, action, "type")) {
            cdp.typeText(target, value) catch {};
        } else if (mem.eql(u8, action, "scroll")) {
            cdp.scrollPage(target, value) catch {};
        } else if (mem.eql(u8, action, "extract")) {
            const extracted = cdp.extractText(target) catch continue;
            defer allocator.free(extracted);
            const note = fmt.allocPrint(ia, "Extracted: {s}", .{extracted}) catch continue;
            try history.appendSlice(note);
            try history.append('\n');
        } else if (mem.eql(u8, action, "submit")) {
            cdp.submitForm(target) catch {};
        }

        // 7. History append
        const hist_entry = fmt.allocPrint(ia, "[{d}] {s}: {s}\n", .{run.iteration, action, target}) catch continue;
        history.appendSlice(hist_entry) catch {};
        if (history.items.len > 3000) {
            const trimmed = history.items[history.items.len - 3000..];
            const new_hist = allocator.dupe(u8, trimmed) catch continue;
            history.clearRetainingCapacity();
            history.appendSlice(new_hist) catch {};
            allocator.free(new_hist);
        }

        if (is_done) break;

        std.time.sleep(500 * std.time.ns_per_ms);
    }

    run.sse_queue.push("{\"type\":\"done\",\"text\":\"Agent finished\"}");
}
