## `main` Függvény

```zig
pub fn main() !void {
    const allocator = gpa.allocator();
    run_registry = RunRegistry.init(allocator);

    const addr = try net.Address.parseIp4("0.0.0.0", LISTEN_PORT);
    var server = try addr.listen(.{ .reuse_address = true });
    defer server.deinit();

    std.debug.print("Agent server listening on :{d}\n", .{LISTEN_PORT});

    while (true) {
        const conn = server.accept() catch continue;
        const args = ConnArgs{ .conn = conn };
        const t = Thread.spawn(.{}, handleConn, .{args}) catch {
            conn.stream.close();
            continue;
        };
        t.detach();
    }
}
