const SseQueue = struct {
    allocator: Allocator,
    items: ArrayList([]u8),
    mutex: Thread.Mutex,
    cond: Thread.Condition,
    done: bool,

    fn init(allocator: Allocator) SseQueue {
        return .{
            .allocator = allocator,
            .items = ArrayList([]u8).init(allocator),
            .mutex = .{},
            .cond = .{},
            .done = false,
        };
    }

    fn deinit(self: *SseQueue) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        for (self.items.items) |item| self.allocator.free(item);
        self.items.deinit();
    }

    fn push(self: *SseQueue, msg: []const u8) void {
        const owned = self.allocator.dupe(u8, msg) catch return;
        self.mutex.lock();
        defer self.mutex.unlock();
        self.items.append(owned) catch {
            self.allocator.free(owned);
            return;
        };
        self.cond.signal();
    }

    fn drain(self: *SseQueue, out: *ArrayList([]u8)) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        for (self.items.items) |item| {
            out.append(item) catch self.allocator.free(item);
        }
        self.items.clearRetainingCapacity();
    }

    fn finish(self: *SseQueue) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        self.done = true;
        self.cond.broadcast();
    }

    fn isDone(self: *SseQueue) bool {
        self.mutex.lock();
        defer self.mutex.unlock();
        return self.done;
    }
};

const AgentRun = struct {
    allocator: Allocator,
    id: []u8,
    task: []u8,
    current_url: []u8,
    iteration: u32,
    max_iterations: u32,
    last_action: []u8,
    running: std.atomic.Value(bool),
    sse_queue: SseQueue,
    state_mutex: Thread.Mutex,

    fn init(allocator: Allocator, id: []const u8, task: []const u8) !*AgentRun {
        const run = try allocator.create(AgentRun);
        errdefer allocator.destroy(run);
        run.* = AgentRun{
            .allocator = allocator,
            .id = try allocator.dupe(u8, id),
            .task = try allocator.dupe(u8, task),
            .current_url = try allocator.dupe(u8, "about:blank"),
            .iteration = 0,
            .max_iterations = MAX_ITERATIONS,
            .last_action = try allocator.dupe(u8, "none"),
            .running = std.atomic.Value(bool).init(true),
            .sse_queue = SseQueue.init(allocator),
            .state_mutex = .{},
        };
        return run;
    }

    fn setCurrentUrl(self: *AgentRun, url: []const u8) void {
        self.state_mutex.lock();
        defer self.state_mutex.unlock();
        const new_url = self.allocator.dupe(u8, url) catch return;
        self.allocator.free(self.current_url);
        self.current_url = new_url;
    }

    fn setLastAction(self: *AgentRun, action: []const u8) void {
        self.state_mutex.lock();
        defer self.state_mutex.unlock();
        const new_action = self.allocator.dupe(u8, action) catch return;
        self.allocator.free(self.last_action);
        self.last_action = new_action;
    }

    fn deinit(self: *AgentRun) void {
        self.sse_queue.deinit();
        self.allocator.free(self.id);
        self.allocator.free(self.task);
        self.allocator.free(self.current_url);
        self.allocator.free(self.last_action);
        self.allocator.destroy(self);
    }
};

const RunRegistry = struct {
    map: std.StringHashMap(*AgentRun),
    lock: Thread.RwLock,

    fn init(allocator: Allocator) RunRegistry {
        return .{
            .map = std.StringHashMap(*AgentRun).init(allocator),
            .lock = .{},
        };
    }

    fn register(self: *RunRegistry, run: *AgentRun) !void {
        self.lock.lock();
        defer self.lock.unlock();
        try self.map.put(run.id, run);
    }

    fn get(self: *RunRegistry, id: []const u8) ?*AgentRun {
        self.lock.lockShared();
        defer self.lock.unlockShared();
        return self.map.get(id);
    }

    fn remove(self: *RunRegistry, id: []const u8) void {
        self.lock.lock();
        defer self.lock.unlock();
        _ = self.map.remove(id);
    }
};

const HttpRequest = struct {
    method: []const u8,
    path: []const u8,
    query: []const u8,
    body: []const u8,
    allocator: Allocator,

    fn deinit(self: *HttpRequest) void {
        if (self.body.len > 0) self.allocator.free(self.body);
    }
};

const ConnArgs = struct {
    conn: net.Server.Connection,
};

const AgentAction = struct {
    thought: []const u8,
    action: []const u8,
    target: []const u8,
    value: []const u8,
    done: bool,
};

fn generateRunId(buf: *[36]u8) void {
    var bytes: [16]u8 = undefined;
    crypto.random.bytes(&bytes);
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    _ = fmt.bufPrint(buf, "{x:0>2}{x:0>2}{x:0>2}{x:0>2}-{x:0>2}{x:0>2}-{x:0>2}{x:0>2}-{x:0>2}{x:0>2}-{x:0>2}{x:0>2}{x:0>2}{x:0>2}{x:0>2}{x:0>2}", .{
        bytes[0], bytes[1], bytes[2], bytes[3],
        bytes[4], bytes[5], bytes[6], bytes[7],
        bytes[8], bytes[9], bytes[10], bytes[11],
        bytes[12], bytes[13], bytes[14], bytes[15],
    }) catch {};
}

fn parseQuery(query: []const u8, key: []const u8) ?[]const u8 {
    var it = mem.tokenizeScalar(u8, query, '&');
    while (it.next()) |part| {
        if (mem.startsWith(u8, part, key)) {
            const rest = part[key.len..];
            if (rest.len > 0 and rest[0] == '=') return rest[1..];
        }
    }
    return null;
}

fn parseJsonField(allocator: Allocator, body: []const u8, field: []const u8) ?[]const u8 {
    const parsed = json.parseFromSlice(json.Value, allocator, body, .{}) catch return null;
    defer parsed.deinit();
    if (parsed.value != .object) return null;
    const value = parsed.value.object.get(field) orelse return null;
    return switch (value) {
        .string => allocator.dupe(u8, value.string) catch null,
        else => null,
    };
}

fn escapeJsonString(allocator: Allocator, s: []const u8) ![]u8 {
    var out = ArrayList(u8).init(allocator);
    errdefer out.deinit();
    for (s) |c| {
        switch (c) {
            '"' => try out.appendSlice("\\\""),
            '\\' => try out.appendSlice("\\\\"),
            '\n' => try out.appendSlice("\\n"),
            '\r' => try out.appendSlice("\\r"),
            '\t' => try out.appendSlice("\\t"),
            0...8, 11, 12, 14...31 => {
                var tmp: [6]u8 = undefined;
                const s2 = try fmt.bufPrint(&tmp, "\\u{x:0>4}", .{c});
                try out.appendSlice(s2);
            },
            else => try out.append(c),
        }
    }
    return out.toOwnedSlice();
}

fn writeHttpResponse(stream: net.Stream, status: u16, content_type: []const u8, body: []const u8, allocator: Allocator) void {
    const status_text = switch (status) {
        200 => "OK",
        204 => "No Content",
        400 => "Bad Request",
        404 => "Not Found",
        405 => "Method Not Allowed",
        500 => "Internal Server Error",
        else => "OK",
    };
    const response = fmt.allocPrint(allocator, "HTTP/1.1 {d} {s}\r\nContent-Type: {s}\r\nContent-Length: {d}\r\nAccess-Control-Allow-Origin: *\r\nConnection: close\r\n\r\n", .{ status, status_text, content_type, body.len }) catch return;
    defer allocator.free(response);
    _ = stream.writeAll(response) catch {};
    _ = stream.writeAll(body) catch {};
}

fn writeSSEHeaders(stream: net.Stream, allocator: Allocator) void {
    const headers = fmt.allocPrint(allocator, "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nCache-Control: no-cache\r\nConnection: keep-alive\r\nAccess-Control-Allow-Origin: *\r\n\r\n", .{}) catch return;
    defer allocator.free(headers);
    _ = stream.writeAll(headers) catch {};
}

fn parseHttpRequest(stream: net.Stream, allocator: Allocator) !HttpRequest {
    var data = ArrayList(u8).init(allocator);
    defer data.deinit();
    var header_end: ?usize = null;
    while (header_end == null and data.items.len < 1024 * 1024) {
        var chunk: [1024]u8 = undefined;
        const n = try stream.read(&chunk);
        if (n == 0) break;
        try data.appendSlice(chunk[0..n]);
        header_end = mem.indexOf(u8, data.items, "\r\n\r\n");
    }
    const hdr_end = header_end orelse return error.BadRequest;
    const raw = data.items[0 .. hdr_end + 4];
    const first_line_end = mem.indexOf(u8, raw, "\r\n") orelse return error.BadRequest;
    const first_line = raw[0..first_line_end];
    var parts = mem.tokenizeScalar(u8, first_line, ' ');
    const method = parts.next() orelse return error.BadRequest;
    const full_path = parts.next() orelse return error.BadRequest;
    const path_end = mem.indexOfScalar(u8, full_path, '?') orelse full_path.len;
    const path = full_path[0..path_end];
    const query = if (path_end < full_path.len) full_path[path_end + 1 ..] else "";
    var content_length: usize = 0;
    var lines_iter = mem.splitSequence(u8, raw[first_line_end + 2 ..], "\r\n");
    while (lines_iter.next()) |line| {
        if (line.len == 0) break;
        const colon = mem.indexOfScalar(u8, line, ':') orelse continue;
        const hname = mem.trim(u8, line[0..colon], " ");
        const hval = mem.trim(u8, line[colon + 1 ..], " ");
        if (std.ascii.eqlIgnoreCase(hname, "content-length")) {
            content_length = fmt.parseInt(usize, hval, 10) catch 0;
        }
    }
    var body: []const u8 = &[_]u8{};
    const body_start = hdr_end + 4;
    if (content_length > 0 and content_length <= 1024 * 1024) {
        const body_buf = try allocator.alloc(u8, content_length);
        const already = @min(content_length, data.items.len - body_start);
        if (already > 0) @memcpy(body_buf[0..already], data.items[body_start .. body_start + already]);
        var read_total = already;
        while (read_total < content_length) {
            const n = try stream.read(body_buf[read_total..content_length]);
            if (n == 0) break;
            read_total += n;
        }
        body = body_buf[0..read_total];
    }
    return HttpRequest{ .method = method, .path = path, .query = query, .body = body, .allocator = allocator };
}

fn checkChromeReady(allocator: Allocator) !bool {
    const stream = net.tcpConnectToAddress(try net.Address.parseIp4("127.0.0.1", CHROME_DEBUG_PORT)) catch return false;
    defer stream.close();
    _ = allocator;
    try stream.writeAll("GET /json/version HTTP/1.1\r\nHost: localhost:9222\r\nConnection: close\r\n\r\n");
    var buf: [2048]u8 = undefined;
    const n = stream.read(&buf) catch return false;
    return n > 0 and mem.indexOf(u8, buf[0..n], "200 OK") != null;
}

fn spawnChrome(allocator: Allocator) !void {
    chrome_mutex.lock();
    defer chrome_mutex.unlock();
    if (chrome_child != null) return;
    const argv = [_][]const u8{
        "google-chrome",
        "--remote-debugging-port=9222",
        "--no-first-run",
        "--no-default-browser-check",
        "--disable-background-networking",
        "--disable-sync",
        "--disable-translate",
        "--disable-extensions",
        "--disable-default-apps",
        "--disable-popup-blocking",
        "--user-data-dir=/tmp/agent-chrome-profile",
        "--headless=new",
    };
    var child = process.Child.init(&argv, allocator);
    child.stdout_behavior = .Ignore;
    child.stderr_behavior = .Ignore;
    try child.spawn();
    chrome_child = child;
    var attempts: u32 = 0;
    while (attempts < 50) : (attempts += 1) {
        std.time.sleep(100 * std.time.ns_per_ms);
        if (try checkChromeReady(allocator)) return;
    }
    return error.ChromeStartTimeout;
}

fn getChromeTargetUrl(allocator: Allocator) ![]u8 {
    const stream = try net.tcpConnectToAddress(try net.Address.parseIp4("127.0.0.1", CHROME_DEBUG_PORT));
    defer stream.close();
    try stream.writeAll("GET /json/new HTTP/1.1\r\nHost: localhost:9222\r\nConnection: close\r\n\r\n");
    var response = ArrayList(u8).init(allocator);
    defer response.deinit();
    var buf: [4096]u8 = undefined;
    while (true) {
        const n = try stream.read(&buf);
        if (n == 0) break;
        try response.appendSlice(buf[0..n]);
    }
    const header_end = mem.indexOf(u8, response.items, "\r\n\r\n") orelse return error.InvalidResponse;
    const body = response.items[header_end + 4 ..];
    const parsed = try json.parseFromSlice(json.Value, allocator, body, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidJson;
    const ws_url = parsed.value.object.get("webSocketDebuggerUrl") orelse return error.NoWsUrl;
    if (ws_url != .string) return error.InvalidWsUrl;
    const path_start = mem.indexOf(u8, ws_url.string, "/devtools") orelse return error.InvalidWsUrl;
    return allocator.dupe(u8, ws_url.string[path_start..]);
}

fn readHttpBody(allocator: Allocator, headers: []const u8, raw_body: []const u8) ![]u8 {
    const is_chunked = mem.indexOf(u8, headers, "chunked") != null or mem.indexOf(u8, headers, "Chunked") != null;
    if (!is_chunked) return allocator.dupe(u8, raw_body);
    var out = ArrayList(u8).init(allocator);
    errdefer out.deinit();
    var pos_idx: usize = 0;
    while (pos_idx < raw_body.len) {
        const crlf_rel = mem.indexOf(u8, raw_body[pos_idx..], "\r\n") orelse break;
        const size_str = mem.trim(u8, raw_body[pos_idx .. pos_idx + crlf_rel], " ");
        const chunk_size = fmt.parseInt(usize, size_str, 16) catch return error.InvalidChunkedEncoding;
        pos_idx += crlf_rel + 2;
        if (chunk_size == 0) break;
        if (pos_idx + chunk_size > raw_body.len) return error.InvalidChunkedEncoding;
        try out.appendSlice(raw_body[pos_idx .. pos_idx + chunk_size]);
        pos_idx += chunk_size;
        if (pos_idx + 2 <= raw_body.len and mem.eql(u8, raw_body[pos_idx .. pos_idx + 2], "\r\n")) pos_idx += 2;
    }
    return out.toOwnedSlice();
}

fn callLlmSimple(allocator: Allocator, user_message: []const u8, api_key: []const u8) ![]u8 {
    const escaped = try escapeJsonString(allocator, user_message);
    defer allocator.free(escaped);
    const messages_json = try fmt.allocPrint(allocator, "[{\"role\":\"user\",\"content\":\"{s}\"}]", .{escaped});
    defer allocator.free(messages_json);
    return callLlmWithMessages(allocator, messages_json, api_key);
}

fn callLlmWithMessages(allocator: Allocator, messages_json: []const u8, api_key: []const u8) ![]u8 {
    const body = try fmt.allocPrint(allocator, "{{\"model\":\"{s}\",\"max_tokens\":24576,\"top_p\":1,\"top_k\":40,\"presence_penalty\":0,\"frequency_penalty\":0,\"temperature\":0.6,\"messages\":{s}}}", .{ FIREWORKS_MODEL, messages_json });
    defer allocator.free(body);
    const auth_header = try fmt.allocPrint(allocator, "Bearer {s}", .{api_key});
    defer allocator.free(auth_header);
    const request = try fmt.allocPrint(allocator,
        "POST /inference/v1/chat/completions HTTP/1.1\r\n" ++
            "Host: {s}\r\n" ++
            "Content-Type: application/json\r\n" ++
            "Accept: application/json\r\n" ++
            "User-Agent: {s}\r\n" ++
            "Authorization: {s}\r\n" ++
            "Content-Length: {d}\r\n" ++
            "Connection: close\r\n\r\n",
        .{ FIREWORKS_HOST, CHROME_UA, auth_header, body.len },
    );
    defer allocator.free(request);
    const tcp = try net.tcpConnectToHost(allocator, FIREWORKS_HOST, 443);
    defer tcp.close();
    var ca_bundle: crypto.Certificate.Bundle = .{};
    try ca_bundle.rescan(allocator);
    defer ca_bundle.deinit(allocator);
    var tls_client = try crypto.tls.Client.init(tcp, .{ .host = .{ .explicit = FIREWORKS_HOST }, .ca = .{ .bundle = ca_bundle } });
    try tls_client.writeAll(tcp, request);
    try tls_client.writeAll(tcp, body);
    var response_buf = ArrayList(u8).init(allocator);
    defer response_buf.deinit();
    var rbuf: [4096]u8 = undefined;
    while (true) {
        const n = tls_client.read(tcp, &rbuf) catch break;
        if (n == 0) break;
        try response_buf.appendSlice(rbuf[0..n]);
    }
    const response = response_buf.items;
    const header_end = mem.indexOf(u8, response, "\r\n\r\n") orelse return error.InvalidResponse;
    const headers = response[0..header_end];
    const resp_body = try readHttpBody(allocator, headers, response[header_end + 4 ..]);
    defer allocator.free(resp_body);
    return extractLlmContent(allocator, resp_body);
}

fn extractLlmContent(allocator: Allocator, body: []const u8) ![]u8 {
    const parsed = try json.parseFromSlice(json.Value, allocator, body, .{});
    defer parsed.deinit();
    const root = parsed.value;
    if (root != .object) return error.InvalidJson;
    const choices = root.object.get("choices") orelse return error.NoChoices;
    if (choices != .array or choices.array.items.len == 0) return error.NoChoices;
    const first = choices.array.items[0];
    if (first != .object) return error.InvalidChoice;
    const msg = first.object.get("message") orelse return error.NoMessage;
    if (msg != .object) return error.InvalidMessage;
    const content = msg.object.get("content") orelse return error.NoContent;
    if (content != .string) return error.InvalidContent;
    return allocator.dupe(u8, content.string);
}

fn callLlmForAgent(allocator: Allocator, task: []const u8, current_url: []const u8, iteration: u32, history: []const u8, dom_snapshot: []const u8, api_key: []const u8) ![]u8 {
    const system_prompt =
        "You are a browser automation agent. You receive the current browser state and must respond with a single JSON object describing the next action. You must always respond with valid JSON only, no prose, no markdown, no code fences.\n\n" ++
        "Action schema:\n" ++
        "{\"thought\":\"string\",\"action\":\"navigate|click|type|scroll|extract|submit|done\",\"target\":\"CSS selector or URL\",\"value\":\"string or empty\",\"done\":false}\n\n" ++
        "Actions:\n" ++
        "- navigate: target is a full URL, value is empty\n" ++
        "- click: target is a CSS selector, value is empty\n" ++
        "- type: target is a CSS selector, value is the text to type\n" ++
        "- scroll: target is up or down, value is pixel amount as string\n" ++
        "- extract: target is a CSS selector, value is empty\n" ++
        "- submit: target is a CSS selector of a form, value is empty\n" ++
        "- done: set done true when the task is fully completed";
    const dom_truncated = if (dom_snapshot.len > 12000) dom_snapshot[0..12000] else dom_snapshot;
    const escaped_system = try escapeJsonString(allocator, system_prompt);
    defer allocator.free(escaped_system);
    const user_content = try fmt.allocPrint(allocator, "Task: {s}\nCurrent URL: {s}\nIteration: {d}/{d}\nPrevious actions: {s}\nCurrent page state:\n{s}", .{ task, current_url, iteration, MAX_ITERATIONS, history, dom_truncated });
    defer allocator.free(user_content);
    const escaped_user = try escapeJsonString(allocator, user_content);
    defer allocator.free(escaped_user);
    const messages_json = try fmt.allocPrint(allocator, "[{\"role\":\"system\",\"content\":\"{s}\"},{\"role\":\"user\",\"content\":\"{s}\"}]", .{ escaped_system, escaped_user });
    defer allocator.free(messages_json);
    return callLlmWithMessages(allocator, messages_json, api_key);
}

const CdpClient = struct {
    stream: net.Stream,
    next_id: u32,
    allocator: Allocator,

    fn connect(allocator: Allocator) !CdpClient {
        try spawnChrome(allocator);
        const target_url = try getChromeTargetUrl(allocator);
        defer allocator.free(target_url);
        const stream = try net.tcpConnectToAddress(try net.Address.parseIp4("127.0.0.1", CHROME_DEBUG_PORT));
        errdefer stream.close();
        var key_bytes: [16]u8 = undefined;
        crypto.random.bytes(&key_bytes);
        var key_b64_buf: [32]u8 = undefined;
        const key_b64 = std.base64.standard.Encoder.encode(&key_b64_buf, &key_bytes);
        const handshake = try fmt.allocPrint(allocator,
            "GET {s} HTTP/1.1\r\n" ++
                "Host: localhost:{d}\r\n" ++
                "Upgrade: websocket\r\n" ++
                "Connection: Upgrade\r\n" ++
                "Sec-WebSocket-Key: {s}\r\n" ++
                "Sec-WebSocket-Version: 13\r\n\r\n",
            .{ target_url, CHROME_DEBUG_PORT, key_b64 },
        );
        defer allocator.free(handshake);
        try stream.writeAll(handshake);
        var resp_buf = ArrayList(u8).init(allocator);
        defer resp_buf.deinit();
        while (mem.indexOf(u8, resp_buf.items, "\r\n\r\n") == null and resp_buf.items.len < 8192) {
            var one: [1]u8 = undefined;
            const n = try stream.read(&one);
            if (n == 0) break;
            try resp_buf.append(one[0]);
        }
        if (!mem.startsWith(u8, resp_buf.items, "HTTP/1.1 101")) return error.WebSocketUpgradeFailed;
        return .{ .stream = stream, .next_id = 1, .allocator = allocator };
    }

    fn deinit(self: *CdpClient) void {
        self.stream.close();
    }

    fn sendFrame(self: *CdpClient, data: []const u8) !void {
        var mask: [4]u8 = undefined;
        crypto.random.bytes(&mask);
        var header: [14]u8 = undefined;
        var hlen: usize = 2;
        header[0] = 0x81;
        if (data.len <= 125) {
            header[1] = 0x80 | @as(u8, @intCast(data.len));
        } else if (data.len <= 65535) {
            header[1] = 0x80 | 126;
            header[2] = @intCast((data.len >> 8) & 0xFF);
            header[3] = @intCast(data.len & 0xFF);
            hlen = 4;
        } else {
            header[1] = 0x80 | 127;
            const len_u64: u64 = @intCast(data.len);
            header[2] = @intCast((len_u64 >> 56) & 0xFF);
            header[3] = @intCast((len_u64 >> 48) & 0xFF);
            header[4] = @intCast((len_u64 >> 40) & 0xFF);
            header[5] = @intCast((len_u64 >> 32) & 0xFF);
            header[6] = @intCast((len_u64 >> 24) & 0xFF);
            header[7] = @intCast((len_u64 >> 16) & 0xFF);
            header[8] = @intCast((len_u64 >> 8) & 0xFF);
            header[9] = @intCast(len_u64 & 0xFF);
            hlen = 10;
        }
        header[hlen] = mask[0];
        header[hlen + 1] = mask[1];
        header[hlen + 2] = mask[2];
        header[hlen + 3] = mask[3];
        hlen += 4;
        const masked = try self.allocator.alloc(u8, data.len);
        defer self.allocator.free(masked);
        for (data, 0..) |b, i| masked[i] = b ^ mask[i % 4];
        try self.stream.writeAll(header[0..hlen]);
        try self.stream.writeAll(masked);
    }

    fn recvFrame(self: *CdpClient, out: *ArrayList(u8)) !bool {
        var header: [2]u8 = undefined;
        try self.stream.readNoEof(&header);
        const fin = (header[0] & 0x80) != 0;
        const opcode = header[0] & 0x0F;
        const masked = (header[1] & 0x80) != 0;
        var payload_len: usize = header[1] & 0x7F;
        if (payload_len == 126) {
            var ext: [2]u8 = undefined;
            try self.stream.readNoEof(&ext);
            payload_len = (@as(usize, ext[0]) << 8) | ext[1];
        } else if (payload_len == 127) {
            var ext: [8]u8 = undefined;
            try self.stream.readNoEof(&ext);
            payload_len = (@as(usize, ext[0]) << 56) | (@as(usize, ext[1]) << 48) | (@as(usize, ext[2]) << 40) | (@as(usize, ext[3]) << 32) | (@as(usize, ext[4]) << 24) | (@as(usize, ext[5]) << 16) | (@as(usize, ext[6]) << 8) | ext[7];
        }
        var mask_key: [4]u8 = undefined;
        if (masked) try self.stream.readNoEof(&mask_key);
        if (payload_len > 10 * 1024 * 1024) return error.PayloadTooLarge;
        const payload = try self.allocator.alloc(u8, payload_len);
        defer self.allocator.free(payload);
        try self.stream.readNoEof(payload);
        if (masked) {
            for (payload, 0..) |*b, i| b.* ^= mask_key[i % 4];
        }
        switch (opcode) {
            0x8 => return error.ConnectionClosed,
            0x9 => {
                var pong_header: [6]u8 = .{ 0x8A, 0x80 | 0, 0, 0, 0, 0 };
                _ = self.stream.writeAll(&pong_header) catch {};
            },
            0xA => {},
            else => try out.appendSlice(payload),
        }
        return fin;
    }

    fn recvMessage(self: *CdpClient) ![]u8 {
        var buf = ArrayList(u8).init(self.allocator);
        errdefer buf.deinit();
        while (true) {
            const fin = try self.recvFrame(&buf);
            if (fin) break;
        }
        return buf.toOwnedSlice();
    }

    fn call(self: *CdpClient, method: []const u8, params: []const u8) ![]u8 {
        const id = self.next_id;
        self.next_id += 1;
        const msg = try fmt.allocPrint(self.allocator, "{{\"id\":{d},\"method\":\"{s}\",\"params\":{s}}}", .{ id, method, params });
        defer self.allocator.free(msg);
        try self.sendFrame(msg);
        const deadline = std.time.milliTimestamp() + 10000;
        while (std.time.milliTimestamp() < deadline) {
            const raw = try self.recvMessage();
            errdefer self.allocator.free(raw);
            const parsed = json.parseFromSlice(json.Value, self.allocator, raw, .{}) catch {
                self.allocator.free(raw);
                continue;
            };
            defer parsed.deinit();
            if (parsed.value != .object) {
                self.allocator.free(raw);
                continue;
            }
            const msg_id = parsed.value.object.get("id") orelse {
                self.allocator.free(raw);
                continue;
            };
            if (msg_id != .integer) {
                self.allocator.free(raw);
                continue;
            }
            if (@as(u32, @intCast(msg_id.integer)) == id) return raw;
            self.allocator.free(raw);
        }
        return error.Timeout;
    }

    fn navigate(self: *CdpClient, url: []const u8) !void {
        const escaped = try escapeJsonString(self.allocator, url);
        defer self.allocator.free(escaped);
        const params = try fmt.allocPrint(self.allocator, "{\"url\":\"{s}\"}", .{escaped});
        defer self.allocator.free(params);
        const result = try self.call("Page.navigate", params);
        defer self.allocator.free(result);
        std.time.sleep(3 * std.time.ns_per_s);
    }

    fn evaluate(self: *CdpClient, expression: []const u8) ![]u8 {
        const escaped = try escapeJsonString(self.allocator, expression);
        defer self.allocator.free(escaped);
        const params = try fmt.allocPrint(self.allocator, "{\"expression\":\"{s}\",\"returnByValue\":true,\"awaitPromise\":true}", .{escaped});
        defer self.allocator.free(params);
        const result = try self.call("Runtime.evaluate", params);
        defer self.allocator.free(result);
        const parsed = try json.parseFromSlice(json.Value, self.allocator, result, .{});
        defer parsed.deinit();
        if (parsed.value != .object) return self.allocator.dupe(u8, "");
        const r = parsed.value.object.get("result") orelse return self.allocator.dupe(u8, "");
        if (r != .object) return self.allocator.dupe(u8, "");
        const rv = r.object.get("result") orelse return self.allocator.dupe(u8, "");
        if (rv != .object) return self.allocator.dupe(u8, "");
        const val = rv.object.get("value") orelse return self.allocator.dupe(u8, "");
        return switch (val) {
            .string => self.allocator.dupe(u8, val.string),
            .integer => fmt.allocPrint(self.allocator, "{d}", .{val.integer}),
            .float => fmt.allocPrint(self.allocator, "{d}", .{val.float}),
            .bool => self.allocator.dupe(u8, if (val.bool) "true" else "false"),
            else => self.allocator.dupe(u8, ""),
        };
    }

    fn clickElement(self: *CdpClient, selector: []const u8) !void {
        const escaped = try escapeJsonString(self.allocator, selector);
        defer self.allocator.free(escaped);
        const script = try fmt.allocPrint(self.allocator,
            "(function(){{var el=document.querySelector(\\\"{s}\\\");if(!el)return \\\"not found\\\";var rect=el.getBoundingClientRect();var x=rect.left+rect.width/2;var y=rect.top+rect.height/2;el.dispatchEvent(new MouseEvent('mousemove',{{bubbles:true,cancelable:true,clientX:x,clientY:y}}));el.dispatchEvent(new MouseEvent('mousedown',{{bubbles:true,cancelable:true,clientX:x,clientY:y,button:0}}));el.dispatchEvent(new MouseEvent('mouseup',{{bubbles:true,cancelable:true,clientX:x,clientY:y,button:0}}));el.click();return \\\"ok\\\";}})()",
            .{escaped},
        );
        defer self.allocator.free(script);
        const result = try self.evaluate(script);
        defer self.allocator.free(result);
    }

    fn typeText(self: *CdpClient, selector: []const u8, text: []const u8) !void {
        try self.clickElement(selector);
        std.time.sleep(300 * std.time.ns_per_ms);
        const escaped_sel = try escapeJsonString(self.allocator, selector);
        defer self.allocator.free(escaped_sel);
        const escaped_text = try escapeJsonString(self.allocator, text);
        defer self.allocator.free(escaped_text);
        const script = try fmt.allocPrint(self.allocator,
            "(function(){{var el=document.querySelector(\\\"{s}\\\");if(!el)return \\\"not found\\\";el.focus();el.value=\\\"{s}\\\";el.dispatchEvent(new Event('input',{{bubbles:true}}));el.dispatchEvent(new Event('change',{{bubbles:true}}));return \\\"ok\\\";}})()",
            .{ escaped_sel, escaped_text },
        );
        defer self.allocator.free(script);
        const result = try self.evaluate(script);
        defer self.allocator.free(result);
    }

    fn scrollPage(self: *CdpClient, direction: []const u8, amount: []const u8) !void {
        const amt = fmt.parseInt(i32, amount, 10) catch 300;
        const dy = if (mem.eql(u8, direction, "up")) -amt else amt;
        const script = try fmt.allocPrint(self.allocator, "window.scrollBy(0,{d});'ok'", .{dy});
        defer self.allocator.free(script);
        const result = try self.evaluate(script);
        defer self.allocator.free(result);
    }

    fn extractText(self: *CdpClient, selector: []const u8) ![]u8 {
        const escaped = try escapeJsonString(self.allocator, selector);
        defer self.allocator.free(escaped);
        const script = try fmt.allocPrint(self.allocator, "(function(){{var el=document.querySelector(\\\"{s}\\\");return el?el.textContent.trim():\\\"not found\\\";}})()", .{escaped});
        defer self.allocator.free(script);
        return self.evaluate(script);
    }

    fn submitForm(self: *CdpClient, selector: []const u8) !void {
        const escaped = try escapeJsonString(self.allocator, selector);
        defer self.allocator.free(escaped);
        const script = try fmt.allocPrint(self.allocator, "(function(){{var el=document.querySelector(\\\"{s}\\\");if(el){{if(typeof el.submit==='function')el.submit();else el.dispatchEvent(new Event('submit',{{bubbles:true,cancelable:true}}));}}return \\\"ok\\\";}})()", .{escaped});
        defer self.allocator.free(script);
        const result = try self.evaluate(script);
        defer self.allocator.free(result);
    }

    fn getCurrentUrl(self: *CdpClient) ![]u8 {
        return self.evaluate("window.location.href");
    }

    fn getDomSnapshot(self: *CdpClient) ![]u8 {
        const script =
            "(function(){" ++
            "function esc(v){return String(v??'');}" ++
            "function cssPath(el){if(!(el instanceof Element))return '';const parts=[];let node=el;while(node&&node.nodeType===1&&parts.length<6){let part=node.tagName.toLowerCase();if(node.id){part+='#'+CSS.escape(node.id);parts.unshift(part);break;}let nth=1;let sib=node;while((sib=sib.previousElementSibling)!=null)nth++;part+=':nth-child('+nth+')';parts.unshift(part);node=node.parentElement;}return parts.join(' > ');}" ++
            "const els=document.querySelectorAll('input,button,a,select,textarea,[role=button],[role=link],[role=checkbox],[role=textbox],[onclick]');" ++
            "const result=[];els.forEach((el,i)=>{const rect=el.getBoundingClientRect();if(rect.width===0&&rect.height===0)return;result.push({i:i,tag:el.tagName.toLowerCase(),type:esc(el.type),id:esc(el.id),name:esc(el.name),placeholder:esc(el.placeholder),value:esc(el.value),text:esc((el.innerText||el.textContent||'').trim().slice(0,80)),selector:cssPath(el)});});return JSON.stringify(result);})()";
        return self.evaluate(script);
    }
};

fn parseAgentAction(allocator: Allocator, raw: []const u8) !AgentAction {
    const parsed = try json.parseFromSlice(json.Value, allocator, raw, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidJson;
    const obj = parsed.value.object;
    const thought_v = obj.get("thought") orelse return error.InvalidJson;
    const action_v = obj.get("action") orelse return error.InvalidJson;
    const target_v = obj.get("target") orelse return error.InvalidJson;
    const value_v = obj.get("value") orelse return error.InvalidJson;
    const done_v = obj.get("done") orelse return error.InvalidJson;
    if (thought_v != .string or action_v != .string or target_v != .string or value_v != .string or done_v != .bool) return error.InvalidJson;
    return .{
        .thought = try allocator.dupe(u8, thought_v.string),
        .action = try allocator.dupe(u8, action_v.string),
        .target = try allocator.dupe(u8, target_v.string),
        .value = try allocator.dupe(u8, value_v.string),
        .done = done_v.bool,
    };
}

fn agentLoop(run: *AgentRun) void {
    defer {
        run.running.store(false, .seq_cst);
        run.sse_queue.finish();
    };
    const allocator = run.allocator;
    const api_key = process.getEnvVarOwned(allocator, "FIREWORKS_API_KEY") catch {
        run.sse_queue.push("{\"type\":\"error\",\"text\":\"Missing FIREWORKS_API_KEY\"}");
        return;
    };
    defer allocator.free(api_key);
    var cdp = CdpClient.connect(allocator) catch |err| {
        const msg = fmt.allocPrint(allocator, "{{\"type\":\"error\",\"text\":\"CDP connect failed: {s}\"}}", .{@errorName(err)}) catch return;
        defer allocator.free(msg);
        run.sse_queue.push(msg);
        return;
    };
    defer cdp.deinit();
    var history = ArrayList(u8).init(allocator);
    defer history.deinit();
    while (run.running.load(.seq_cst) and run.iteration < run.max_iterations) {
        var iter_arena = std.heap.ArenaAllocator.init(allocator);
        defer iter_arena.deinit();
        const ia = iter_arena.allocator();
        run.iteration += 1;
        const dom = cdp.getDomSnapshot() catch allocator.dupe(u8, "[]") catch return;
        defer allocator.free(dom);
        const url = cdp.getCurrentUrl() catch allocator.dupe(u8, "about:blank") catch return;
        defer allocator.free(url);
        run.setCurrentUrl(url);
        const llm_response = callLlmForAgent(ia, run.task, url, run.iteration, history.items, dom, api_key) catch |err| {
            const msg = fmt.allocPrint(allocator, "{{\"type\":\"error\",\"text\":\"LLM error: {s}\"}}", .{@errorName(err)}) catch return;
            defer allocator.free(msg);
            run.sse_queue.push(msg);
            break;
        };
        const action = parseAgentAction(ia, llm_response) catch {
            run.sse_queue.push("{\"type\":\"error\",\"text\":\"Invalid LLM JSON\"}");
            continue;
        };
        const esc_thought = escapeJsonString(ia, action.thought) catch continue;
        const esc_action = escapeJsonString(ia, action.action) catch continue;
        const esc_target = escapeJsonString(ia, action.target) catch continue;
        const log_msg = fmt.allocPrint(ia, "{{\"type\":\"step\",\"iteration\":{d},\"thought\":\"{s}\",\"action\":\"{s}\",\"target\":\"{s}\"}}", .{ run.iteration, esc_thought, esc_action, esc_target }) catch continue;
        run.sse_queue.push(log_msg);
        run.setLastAction(action.action);
        if (mem.eql(u8, action.action, "navigate")) {
            _ = cdp.navigate(action.target) catch {};
        } else if (mem.eql(u8, action.action, "click")) {
            _ = cdp.clickElement(action.target) catch {};
        } else if (mem.eql(u8, action.action, "type")) {
            _ = cdp.typeText(action.target, action.value) catch {};
        } else if (mem.eql(u8, action.action, "scroll")) {
            _ = cdp.scrollPage(action.target, action.value) catch {};
        } else if (mem.eql(u8, action.action, "extract")) {
            const extracted = cdp.extractText(action.target) catch allocator.dupe(u8, "") catch continue;
            defer allocator.free(extracted);
            const note = fmt.allocPrint(ia, "Extracted: {s}\n", .{extracted}) catch continue;
            history.appendSlice(note) catch {};
        } else if (mem.eql(u8, action.action, "submit")) {
            _ = cdp.submitForm(action.target) catch {};
        } else if (mem.eql(u8, action.action, "done")) {
            const done_msg = fmt.allocPrint(ia, "{{\"type\":\"done\",\"text\":\"{s}\"}}", .{"Agent finished"}) catch continue;
            run.sse_queue.push(done_msg);
            break;
        }
        const hist_entry = fmt.allocPrint(ia, "[{d}] {s}: {s}\n", .{ run.iteration, action.action, action.target }) catch continue;
        history.appendSlice(hist_entry) catch {};
        if (history.items.len > 3000) {
            const trimmed = history.items[history.items.len - 3000 ..];
            var new_history = ArrayList(u8).init(allocator);
            defer new_history.deinit();
            new_history.appendSlice(trimmed) catch {};
            history.clearRetainingCapacity();
            history.appendSlice(new_history.items) catch {};
        }
        if (action.done) break;
        std.time.sleep(500 * std.time.ns_per_ms);
    }
    run.sse_queue.push("{\"type\":\"done\",\"text\":\"Agent finished\"}");
}

fn handleTaskPost(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const task = parseJsonField(allocator, req.body, "task") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing task\"}", allocator);
        return;
    };
    defer allocator.free(task);
    var id_buf: [36]u8 = undefined;
    generateRunId(&id_buf);
    const run = AgentRun.init(gpa.allocator(), &id_buf, task) catch {
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"internal error\"}", allocator);
        return;
    };
    run_registry.register(run) catch {
        run.deinit();
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"registry error\"}", allocator);
        return;
    };
    const thread = Thread.spawn(.{}, agentLoop, .{run}) catch {
        run_registry.remove(run.id);
        run.deinit();
        writeHttpResponse(stream, 500, "application/json", "{\"error\":\"spawn error\"}", allocator);
        return;
    };
    thread.detach();
    const resp = fmt.allocPrint(allocator, "{{\"status\":\"started\",\"id\":\"{s}\"}}", .{run.id}) catch return;
    defer allocator.free(resp);
    writeHttpResponse(stream, 200, "application/json", resp, allocator);
}

fn handleEvents(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const run_id = parseQuery(req.query, "id") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing id\"}", allocator);
        return;
    };
    const run = run_registry.get(run_id) orelse {
        writeHttpResponse(stream, 404, "application/json", "{\"error\":\"not found\"}", allocator);
        return;
    };
    writeSSEHeaders(stream, allocator);
    var buf = ArrayList([]u8).init(allocator);
    defer {
        for (buf.items) |item| gpa.allocator().free(item);
        buf.deinit();
    }
    while (true) {
        run.sse_queue.drain(&buf);
        for (buf.items) |item| {
            const line = fmt.allocPrint(allocator, "data: {s}\n\n", .{item}) catch continue;
            defer allocator.free(line);
            stream.writeAll(line) catch return;
            gpa.allocator().free(item);
        }
        buf.clearRetainingCapacity();
        if (run.sse_queue.isDone()) {
            _ = stream.writeAll("data: {\"type\":\"done\"}\n\n") catch {};
            return;
        }
        std.time.sleep(200 * std.time.ns_per_ms);
    }
}

fn handleStatus(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const run_id = parseQuery(req.query, "id") orelse {
        writeHttpResponse(stream, 400, "application/json", "{\"error\":\"missing id\"}", allocator);
        return;
    };
    const run = run_registry.get(run_id) orelse {
        writeHttpResponse(stream, 404, "application/json", "{\"error\":\"not found\"}", allocator);
        return;
    };
    run.state_mutex.lock();
    defer run.state_mutex.unlock();
    const esc_url = escapeJsonString(allocator, run.current_url) catch return;
    defer allocator.free(esc_url);
    const esc_action = escapeJsonString(allocator, run.last_action) catch return;
    defer allocator.free(esc_action);
    const resp = fmt.allocPrint(allocator, "{{\"running\":{s},\"iteration\":{d},\"current_url\":\"{s}\",\"last_action\":\"{s}\"}}", .{ if (run.running.load(.seq_cst)) "true" else "false", run.iteration, esc_url, esc_action }) catch return;
    defer allocator.free(resp);
    writeHttpResponse(stream, 200, "application/json", resp, allocator);
}

fn handleStop(stream: net.Stream, req: *HttpRequest, allocator: Allocator) void {
    const run_id = parseQuery(req.query, "id") orelse {
